import{_ as r,o,c as a,a5 as n}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"877-批量图片去重工具-哈希值结合局部敏感度判断-V2.0","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["图片批处理"],"标签":["Python图片处理","图片去重工具","图片去重算法","图片批量管理","图片整理工具","图片相似度检测","批量删除重复图片","批量文件处理","文件去重软件","重复图片清理"]},"headers":[],"relativePath":"md/图片批处理/877-批量图片去重工具-哈希值结合局部敏感度判断-V2.0.md","filePath":"md/图片批处理/877-批量图片去重工具-哈希值结合局部敏感度判断-V2.0.md"}'),l={name:"md/图片批处理/877-批量图片去重工具-哈希值结合局部敏感度判断-V2.0.md"};function i(s,t,g,e,p,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<p>批量检测删除重复图片，能够快速识别和处理文件夹中的重复图片。该工具使用图像哈希算法（LSH哈希和感知哈希）来检测图片相似度，支持批量处理大量图片文件，有效释放存储空间。</p><p>工具支持多种常见图片格式，包括.jpg&#39;, &#39;.jpeg&#39;, &#39;.png&#39;, &#39;.gif&#39;, &#39;.bmp&#39;, &#39;.tiff&#39;, &#39;.webp，不区分扩展名大小写。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128224349176961142956928.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>智能图片去重</strong>：结合LSH哈希和感知哈希两种算法，提高重复图片检测的准确性，确保不会误删不相似的图片</li><li><strong>灵活的去重模式</strong>：<strong>支持”仅移动不删除”和”直接删除”两种模式</strong>，用户可以根据需要选择安全模式或快速清理模式</li><li><strong>全局去重选项</strong>：<strong>支持跨文件夹全局比较</strong>，可以检测不同子文件夹之间的重复图片，实现全面的去重处理</li><li><strong>可调节相似度阈值</strong>：用户可以自定义相似度阈值（推荐范围1-20），根据实际需求调整去重的严格程度</li><li><strong>安全的文件处理</strong>：移动模式下，重复图片会被移动到”待确认重复图片”文件夹，并保留原始路径映射，支持一键恢复</li><li><strong>多线程处理</strong>：采用多线程技术，确保在处理大量图片时界面保持响应，不会出现卡顿现象</li><li><strong>实时日志显示</strong>：提供详细的操作日志，实时显示处理进度和结果，方便用户了解处理情况</li><li><strong>自然排序支持</strong>：文件夹和文件按自然顺序排序（1, 2, 10），避免传统排序导致的混乱</li><li><strong>操作可中断</strong>：支持随时停止正在进行的处理任务，提供更好的用户控制体验</li></ul><h3 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h3><ol><li><strong>启动程序</strong>：运行程序</li><li><strong>选择文件夹</strong>：<strong>点击”选择文件夹”按钮，浏览并选择包含待处理图片的文件夹路径</strong></li><li><strong>设置阈值</strong>：在”相似度阈值”输入框中设置阈值数值，默认为10，推荐范围1-20，根据实际情况测试符合自己的数值</li><li><strong>选择模式</strong>： <ul><li>勾选”仅移动不删除”：重复图片将被移动到待确认文件夹</li><li>不勾选：重复图片将被直接删除</li></ul></li><li><strong>开始处理</strong>：<strong>点击”开始程序”按钮，工具将自动开始检测和处理重复图片</strong></li><li><strong>查看结果</strong>：在日志窗口中查看处理进度和结果</li></ol><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><h3 id="相似度阈值说明" tabindex="-1">相似度阈值说明 <a class="header-anchor" href="#相似度阈值说明" aria-label="Permalink to &quot;相似度阈值说明&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128225211176961193149106.png" alt=""></p><p>相似度阈值用于判断两张图片是否为重复图片的标准：</p><ul><li>阈值越小，判定越严格，只有非常相似的图片才会被识别为重复</li><li>阈值越大，判定越宽松，相似度较低的图片也可能被识别为重复</li><li>推荐范围：1-20，默认值为10</li></ul><h3 id="去重模式选择" tabindex="-1">去重模式选择 <a class="header-anchor" href="#去重模式选择" aria-label="Permalink to &quot;去重模式选择&quot;">​</a></h3><h3 id="仅移动不删除模式" tabindex="-1"><strong>仅移动不删除模式</strong>： <a class="header-anchor" href="#仅移动不删除模式" aria-label="Permalink to &quot;**仅移动不删除模式**：&quot;">​</a></h3><ul><li>勾选此选项后，重复图片不会被删除，而是移动到”待确认重复图片”文件夹</li><li>移动的文件会保留原始目录结构</li><li>系统会自动创建映射文件记录原始路径，方便后续恢复</li><li><strong>此模式更安全，适合初次使用或不确定的情况</strong></li></ul><h3 id="直接删除模式" tabindex="-1"><strong>直接删除模式</strong>： <a class="header-anchor" href="#直接删除模式" aria-label="Permalink to &quot;**直接删除模式**：&quot;">​</a></h3><ul><li>不勾选”仅移动不删除”选项，重复图片将被直接删除</li><li>删除操作不可恢复，请谨慎使用</li><li><strong>此模式适合确定要删除的重复图片</strong></li></ul><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128225236176961195656940.png" alt=""></p><h3 id="全局去重功能" tabindex="-1">全局去重功能 <a class="header-anchor" href="#全局去重功能" aria-label="Permalink to &quot;全局去重功能&quot;">​</a></h3><p>勾选”全局去重”选项后，程序会在所有子文件夹之间进行重复图片比较，实现跨文件夹去重。不勾选时，每个子文件夹内部独立进行去重，不会跨文件夹比较。</p><h3 id="恢复移动文件" tabindex="-1">恢复移动文件 <a class="header-anchor" href="#恢复移动文件" aria-label="Permalink to &quot;恢复移动文件&quot;">​</a></h3><p>点击”恢复移动文件”按钮，可以将之前移动到”待确认重复图片”文件夹的图片恢复到原始位置。如果原始位置已有同名文件，会自动添加”<em>restored</em>“后缀避免覆盖。</p><h3 id="删除待确认目录" tabindex="-1">删除待确认目录 <a class="header-anchor" href="#删除待确认目录" aria-label="Permalink to &quot;删除待确认目录&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128225346176961202683994.jpg" alt=""></p><p>点击”删除待确认目录”按钮，可以彻底删除”待确认重复图片”文件夹及其中的所有文件。此操作不可恢复，删除前会有确认提示。</p><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><p><strong>场景一：整理手机相册</strong></p><p>用户将手机中的照片备份到电脑，由于多次备份导致存在大量重复照片。使用本工具可以快速识别并清理重复照片：</p><ol><li>将手机照片文件夹路径输入到程序中</li><li>设置相似度阈值为8（较严格）</li><li>勾选”仅移动不删除”选项</li><li>点击开始程序</li><li>检查”待确认重复图片”文件夹中的内容</li><li>确认无误后，可以删除待确认目录</li></ol><p><strong>场景二：清理设计素材库</strong></p><p>设计师在长期工作中积累了大量设计素材，其中包含大量相似或重复的图片。使用本工具可以高效整理素材库：</p><ol><li>选择设计素材文件夹</li><li>设置相似度阈值为12（较宽松，因为设计素材可能有细微差异）</li><li>勾选”全局去重”选项，实现跨文件夹去重</li><li>点击开始程序</li><li>根据日志查看处理结果</li><li>确认后删除待确认目录</li></ol><p><strong>场景三：批量处理产品图片</strong></p><p>电商卖家需要处理大量产品图片，由于多次拍摄和编辑，存在大量重复或相似图片。使用本工具可以快速清理：</p><ol><li>选择产品图片文件夹</li><li>设置相似度阈值为10（默认值）</li><li>不勾选”仅移动不删除”，直接删除重复图片</li><li>点击开始程序</li><li>观察日志确保处理正确</li><li>完成后获得清理后的图片库</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><strong>数据安全：建议首次使用时勾选”仅移动不删除”选项，检查待确认文件夹内容后再决定是否删除</strong></li><li><strong>阈值设置：相似度阈值设置过小可能导致漏掉真正的重复图片，设置过大可能误删不相似的图片，请根据实际情况调整</strong></li><li><strong>备份重要数据：在使用直接删除模式前，建议先备份重要图片数据</strong></li><li><strong>处理大文件夹：处理包含大量图片的文件夹时，可能需要较长时间，请耐心等待</strong></li><li>待确认文件夹会被自动跳过，不会重复处理已移动的文件</li><li>恢复文件时，如果原始位置已有同名文件，会自动添加后缀避免覆盖</li><li>删除待确认目录操作不可恢复，请谨慎操作</li></ul><h3 id="使用场景例子展示" tabindex="-1">使用场景例子展示 <a class="header-anchor" href="#使用场景例子展示" aria-label="Permalink to &quot;使用场景例子展示&quot;">​</a></h3><p>A文件夹下有很多图片文件，同时有B、C、D....等文件夹，B、C、D....等这些文件夹下边还有子文件夹，子文件夹下也有图片文件。</p><p>【操作方法】：只需要输入A文件夹路径即可，支持子文件夹自动穿透（勾选全局去重后，A文件夹下所有文件都会参与到去重中，只保留一个，删除其他重复的文件）</p><p>【1】、支持的文件格式：.jpg&#39;, &#39;.jpeg&#39;, &#39;.png&#39;, &#39;.gif&#39;, &#39;.bmp&#39;, &#39;.tiff&#39;, &#39;.webp，不区分扩展名大小写。</p><p>【2】、是否支持子文件夹穿透：支持</p><h3 id="文件结构树示意" tabindex="-1">文件结构树示意 <a class="header-anchor" href="#文件结构树示意" aria-label="Permalink to &quot;文件结构树示意&quot;">​</a></h3><p><strong>文件夹A/ (主文件夹)</strong><br> ├── 文件1<br> ├── 文件2<br> ├── <strong>B/ (子文件夹)</strong><br> │   ├── 文件3<br> │   ├── <strong>子文件夹B1/</strong><br> │   │   ├── 文件4<br> │   │   └── <strong>子文件夹B1a/</strong><br> │   │       └── 文件5<br> │   └── <strong>子文件夹B2/</strong><br> │       └── 文件6<br> │       ... (B文件夹下可能还有更多子文件夹和文件)<br> ├── <strong>C/ (子文件夹)</strong><br> │   ├── 文件7<br> │   └── <strong>子文件夹C1/</strong><br> │       ├── 文件8<br> │       └── <strong>子文件夹C1a/</strong><br> │           └── 文件9<br> │           ... (C1a文件夹下可能还有更多嵌套)<br> └── <strong>D/ (子文件夹)</strong><br>     ├── 文件10<br>     └── <strong>子文件夹D1/</strong><br>         └── 文件11<br>         ... (D1文件夹下可能还有更多文件)<br><strong>... (A文件夹下可能还有更多子文件夹如E/F/G等)</strong></p><p>注意：先测试备份原文件再批量使用</p><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128224349176961142956928.png" alt=""></p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 程序提示”请输入文件夹路径”怎么办？</strong></p><p>A: 请确保在”图片所在文件夹路径”输入框中输入了有效的文件夹路径，或点击”选择文件夹”按钮选择一个文件夹。</p><p><strong>Q: 相似度阈值应该设置多少？</strong></p><p>A: 推荐范围是1-20，默认值为10。阈值越小，判定越严格；阈值越大，判定越宽松。建议从默认值开始，根据实际效果调整。</p><p><strong>Q: “仅移动不删除”和直接删除有什么区别？</strong></p><p>A: “仅移动不删除”模式会将重复图片移动到”待确认重复图片”文件夹，可以随时恢复；直接删除模式会永久删除重复图片，不可恢复。建议首次使用时选择”仅移动不删除”模式。</p><p><strong>Q: 全局去重是什么意思？</strong></p><p>A: 全局去重是指程序会在所有子文件夹之间比较图片，检测跨文件夹的重复图片。不勾选时，每个子文件夹内部独立去重。</p><p><strong>Q: 如何恢复被移动的文件？</strong></p><p>A: 点击”恢复移动文件”按钮，程序会将”待确认重复图片”文件夹中的文件恢复到原始位置。</p><p><strong>Q: 处理过程中可以停止吗？</strong></p><p>A: 可以，点击”结束任务”按钮可以随时停止正在进行的处理任务。</p><p><strong>Q: 支持哪些图片格式？</strong></p><p>A: 支持JPG、JPEG、PNG、GIF、BMP、TIFF、WEBP等常见图片格式。</p><p><strong>Q: 程序运行很慢怎么办？</strong></p><p>A: 处理大量图片时需要一定时间，这是正常现象。如果处理速度异常慢，可以尝试提高相似度阈值或减少处理的图片数量。</p><p><strong>Q: 待确认文件夹可以删除吗？</strong></p><p>A: 可以，点击”删除待确认目录”按钮可以删除待确认文件夹。但此操作不可恢复，请确认不再需要这些文件后再删除。</p><p><strong>Q: 程序会修改原始图片吗？</strong></p><p>A: 不会。程序只会移动或删除重复图片，不会修改任何图片的内容或质量。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，看到如下文件，双击快捷方式使用即可（快捷方式上有个箭头），快捷方式可以放到任意位置。</strong></p><p><strong>如下所示，文件夹及文件夹内所有内容都不要删除，如果突然无法使用了大概率是杀毒软件给误杀了，请重新解压使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260128230622176961278248854.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2436.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2436.html</a></p>',79)])])}const c=r(l,[["render",i]]);export{d as __pageData,c as default};
